const data = msg.payload;
if (!data || typeof data !== "object" || Array.isArray(data)) {
  node.warn("Invalid scene payload");
  return null;
}
const objects = data.objects ?? {};
if (typeof objects !== "object") {
  node.warn("Invalid scene objects");
  return null;
}

const objectPerCategory = Object.create(null);
for (const object of Object.values(objects)) {
  if (!object || typeof object.category !== "string" || !object.category.trim()) continue;
  objectPerCategory[object.category] = (objectPerCategory[object.category] ?? 0) + 1;
}

msg.payload = {
  scene_name: data.name,
  scene_id: data.id,
  timestamp: data.timestamp,
  objectPerCategory,
};
return msg;

const data = msg.payload;
if (!data || typeof data !== "object" || Array.isArray(data)) {
  node.warn("Invalid ROI payload");
  return null;
}
if (!data.counts || typeof data.counts !== "object" || Array.isArray(data.counts)) {
  node.warn("Invalid ROI counts");
  return null;
}
const counts = Object.values(data.counts);
if (!counts.every(value => Number.isFinite(value) && value >= 0)) {
  node.warn("ROI counts must be nonnegative finite numbers");
  return null;
}
const occupancy = counts.reduce((total, value) => total + value, 0);
if (!Number.isFinite(occupancy)) {
  node.warn("Invalid ROI occupancy total");
  return null;
}

msg.payload = {
  scene_name: data.scene_name,
  scene_id: data.scene_id,
  region_name: data.region_name,
  region_id: data.region_id,
  timestamp: data.timestamp,
  occupancy,
};
return msg;

const data = msg.payload;
if (!data || typeof data !== "object" || Array.isArray(data)) {
  node.warn("Invalid tripwire payload");
  return null;
}
const points = data.metadata?.points;
if (!Array.isArray(points) || points.length < 2 || !points.slice(0, 2).every(point => Array.isArray(point) && point.length >= 2 && Number.isFinite(point[0]) && Number.isFinite(point[1]))) {
  node.warn("Tripwire event needs two finite coordinate pairs");
  return null;
}

const dx = points[1][0] - points[0][0];
const dy = points[1][1] - points[0][1];
if (!Number.isFinite(dx) || !Number.isFinite(dy) || (dx === 0 && dy === 0)) {
  node.warn("Tripwire endpoints must differ with finite displacement");
  return null;
}
const objects = data.objects ?? [];
if (!Array.isArray(objects)) {
  node.warn("Tripwire objects must be an array");
  return null;
}
const horizontal = Math.abs(dx) >= Math.abs(dy);
const positiveDirection = horizontal ? (dx > 0 ? "down" : "up") : (dy > 0 ? "right" : "left");
const negativeDirection = horizontal ? (dx > 0 ? "up" : "down") : (dy > 0 ? "left" : "right");

msg.payload = {
  scene_name: data.scene_name,
  scene_id: data.scene_id,
  tripwire_name: data.tripwire_name,
  tripwire_id: data.tripwire_id,
  timestamp: data.timestamp,
  objects: objects.filter(object => object && typeof object.category === "string" && object.category.trim() && (object.direction === 1 || object.direction === -1)).map(object => ({
    category: object.category,
    direction: object.direction === 1 ? positiveDirection : negativeDirection,
  })),
};
return msg;

const data = msg.payload;
const isRecord = value => value !== null && typeof value === "object" && !Array.isArray(value);
const validId = value => typeof value === "string" && value.trim().length > 0 && !["__proto__", "constructor", "prototype"].includes(value);
if (!isRecord(data) || !validId(data.scene_id)) {
  node.warn("Scene update requires a valid scene ID");
  return null;
}
let scenes = flow.get("scenes");
if (!isRecord(scenes)) scenes = {};
const scene = isRecord(scenes[data.scene_id]) ? scenes[data.scene_id] : {};

scene.name = data.scene_name;
scene.id = data.scene_id;
scene.objectPerCategory = isRecord(data.objectPerCategory) ? data.objectPerCategory : {};

scenes[data.scene_id] = scene;
flow.set("scenes", scenes);
return msg;

const data = msg.payload;
const isRecord = value => value !== null && typeof value === "object" && !Array.isArray(value);
const validId = value => typeof value === "string" && value.trim().length > 0 && !["__proto__", "constructor", "prototype"].includes(value);
if (!isRecord(data) || !validId(data.scene_id) || !validId(data.region_id)) {
  node.warn("ROI update requires valid scene and region IDs");
  return null;
}
if (!Number.isFinite(data.occupancy) || data.occupancy < 0) {
  node.warn("Invalid ROI occupancy");
  return null;
}
let scenes = flow.get("scenes");
if (!isRecord(scenes)) scenes = {};
const scene = isRecord(scenes[data.scene_id]) ? scenes[data.scene_id] : {};

scene.name = data.scene_name;
scene.id = data.scene_id;

const regions = isRecord(scene.regions) ? scene.regions : {};
const region = isRecord(regions[data.region_id]) ? regions[data.region_id] : {};
region.name = data.region_name;
region.occupancy = data.occupancy;
regions[data.region_id] = region;
scene.regions = regions;

scenes[data.scene_id] = scene;
flow.set("scenes", scenes);
return msg;

const data = msg.payload;
const isRecord = value => value !== null && typeof value === "object" && !Array.isArray(value);
const validId = value => typeof value === "string" && value.trim().length > 0 && !["__proto__", "constructor", "prototype"].includes(value);
if (!isRecord(data) || !validId(data.scene_id) || !validId(data.tripwire_id)) {
  node.warn("Tripwire update requires valid scene and tripwire IDs");
  return null;
}
const objects = data.objects ?? [];
if (!Array.isArray(objects)) {
  node.warn("Tripwire objects must be an array");
  return null;
}
let scenes = flow.get("scenes");
if (!isRecord(scenes)) scenes = {};
const now = Date.now();
const scene = isRecord(scenes[data.scene_id]) ? scenes[data.scene_id] : {};

scene.name = data.scene_name;
scene.id = data.scene_id;

const tripwires = isRecord(scene.tripwires) ? scene.tripwires : {};
const tripwire = isRecord(tripwires[data.tripwire_id]) ? tripwires[data.tripwire_id] : {};
tripwire.name = data.tripwire_name;
tripwire.objects = objects.filter(object => isRecord(object) && typeof object.category === "string" && object.category.trim() && ["up", "down", "left", "right"].includes(object.direction));
tripwire.events = Array.isArray(tripwire.events) ? tripwire.events : [];
tripwire.objects.forEach(function (object) {
  tripwire.events.unshift({
    date: now,
    category: object.category,
    direction: object.direction,
  });
});

tripwires[data.tripwire_id] = tripwire;
scene.tripwires = tripwires;
scenes[data.scene_id] = scene;
flow.set("scenes", scenes);
return msg;

const isRecord = value => value !== null && typeof value === "object" && !Array.isArray(value);
const storedScenes = flow.get("scenes");
const scenes = isRecord(storedScenes) ? storedScenes : {};
const cutoff = Date.now() - 30_000;

Object.entries(scenes).forEach(function ([sceneId, scene]) {
  if (!isRecord(scene)) {
    delete scenes[sceneId];
    return;
  }
  if (!isRecord(scene.tripwires)) scene.tripwires = {};
  Object.entries(scene.tripwires).forEach(function ([tripwireId, tripwire]) {
    if (!isRecord(tripwire)) {
      delete scene.tripwires[tripwireId];
      return;
    }
    const events = Array.isArray(tripwire.events) ? tripwire.events : [];
    tripwire.events = events.filter(event => isRecord(event) && Number.isFinite(event.date) && event.date >= cutoff && typeof event.category === "string" && event.category.trim() && ["up", "down", "left", "right"].includes(event.direction));
  });
});

flow.set("scenes", scenes);
msg.payload = Object.fromEntries(Object.entries(scenes).sort(function ([, firstScene], [, secondScene]) {
  const firstName = typeof firstScene.name === "string" ? firstScene.name : "";
  const secondName = typeof secondScene.name === "string" ? secondScene.name : "";
  return firstName.localeCompare(secondName, "en", { sensitivity: "base" });
}));
return msg;
